def triangle_type(a: float, b: float, c: float) -> str:
    """Return "equilateral", "isosceles", "scalene" or "invalid"."""
    # Ensure all sides are positive and they form a valid triangle
    if a <= 0 or b <= 0 or c <= 0 or a + b <= c or a + c <= b or b + c <= a:
        return "invalid"

    # Check if all sides are equal
    if a == b == c:
        return "equilateral"

    # Check if exactly two sides are equal
    if a == b or b == c or a == c:
        return "isosceles"

    # If none of the above conditions are met, it's scalene
    return "scalene"

