    # Check if all sides are greater than 0 and not equal to the sum of the other two
    if any(s < 0 or s == a + b or s == a + c or s == b + c for s in [a, b, c]):
        return "invalid"

    # Check if all sides are equal (equilateral)
    if a == b == c:
        return "equilateral"

    # Check if exactly two sides are equal (isosceles)
    if a == b or a == c or b == c:
        return "isosceles"

    # If none of the above conditions are met, the triangle is scalene
    return "scalene"

