    if a <= 0 or b <= 0 or c <= 0 or a + b <= c or a + c <= b or b + c <= a:
        return "invalid"

    # Check for equilateral triangle
    if a == b == c:
        return "equilateral"

    # Check for isosceles triangle
    if a == b or b == c or a == c:
        return "isosceles"

    # If none of the above, it is scalene
    return "scalene"

